import gkm_try as H
import perception as P
import numpy as np
from collections import deque
import json

def positions(e):
 f=P.arr(e.frame());return tuple((int(y),int(x)) for y,x in zip(*np.where(f[11:57:5,11:52:5]==10)))
def probe(env):
 f=P.arr(env.frame())[11:57:5,11:52:5]
 walk=set(zip(*np.where((f==5)|(f==10))))
 start=positions(env);print('walk', [''.join('.' if (y,x) in walk else '#' for x in range(9)) for y in range(10)],'start',start)
 dirs={1:(-1,0),2:(1,0),3:(0,-1),4:(0,1)}
 def nxt(s,a):
  out=[]
  for i,(y,x) in enumerate(s):
   dy,dx=dirs[a]; dx=dx if i==0 else -dx
   q=y+dy,x+dx;out.append(q if q in walk else (y,x))
  return tuple(out)
 q=deque([(start,[])]);seen={start};path=None
 while q:
  s,p=q.popleft()
  if s[0]==s[1]:path=p;break
  for a in dirs:
   t=nxt(s,a)
   if t not in seen:seen.add(t);q.append((t,p+[a]))
 print('model_states',len(seen),'path',path)
 if path:
  c=env.clone();s=start
  for i,a in enumerate(path):
   P.safe_step(c,a);s=nxt(s,a)
   obs=positions(c)
   print('step',i+1,a,'pred',s,'obs',obs,'level',c.levels_completed)
   if c.levels_completed>env.levels_completed:
    json.dump(path[:i+1],open('meeting_candidate.json','w'));break
   if obs"'!=tuple(sorted(s)):
    print('"'mismatch');break
H.A.run_program('m0r0',probe)
